import type { VariableConfig } from '../../Variable';
/**
 * Configuration type for duration variables
 */
export type DurationVariableType<Type extends string | number = string | number> = VariableConfig<Type>;
/**
 * A Variable for a duration field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the duration variable including:
 *   * **question** - Question text displayed to the user
 *   * **defaultValue**? - Default value for the variable
 *   * And all other properties from the base Variable type
 */
export declare function DurationVariable(config: DurationVariableType): DurationVariableType<string | number>;
